//! Literal pin tables for the serP/desP oracle (G14/G22/G13, leaf L01-C), part 1: open/closed geometry and
//! stroke/paint fields. Generated by tools/mkpins.cjs from the baseline oracle and reviewed by hand; each row is
//! `(case id, value path, literal)`. Literal grammar: `!` undefined, `^` null, `T`/`F`, decimal numbers (`-0` is
//! negative zero), JSON strings, arrays and objects. A path walks object keys and array indexes
//! (`out.segments.1.point`); a missing key reads as `!`.

pub(crate) type Pin = (&'static str, &'static str, &'static str);

